const icon = (n, c = '') => `<svg class="${c}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n] || paths.arrow}"/></svg>`;
const button = (text, action, cls = 'primary', sym = '') => `<button type="button" class="${cls}" data-action="${action}">${sym ? icon(sym) : ''}${text}</button>`;
const tag = (text, tone = '') => `<span class="tag ${tone}">${text}</span>`;
const section = (text, action = '', label = 'Открыть') => `<div class="section"><h3>${text}</h3>${action ? button(label, action, 'link') : ''}</div>`;
const row = (sym, text, sub, action, tail = '') => `<button class="row" type="button" data-action="${action}"><span class="tile">${icon(sym)}</span><span class="copy"><strong>${text}</strong>${sub ? `<small>${sub}</small>` : ''}</span>${tail}${icon('arrow','chev')}</button>`;
const card = html => `<section class="card">${html}</section>`;
const field = (label, name, value = '', type = 'text', extra = '') => `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const select = (label, name, options, value = '') => `<label class="field">${label}<select name="${name}">${options.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${t}</option>`).join('')}</select></label>`;
const metrics = items => `<div class="metrics">${items.map(([value,label,sub])=>`<div class="metric"><small>${label}</small><strong>${value}</strong><small>${sub}</small></div>`).join('')}</div>`;
const saveBar = (label, action) => `<div class="action-bar">${button(label,action)}</div>`;
