const clients = [{name:'Анна Смирнова',initials:'АС',goal:'Снижение веса',attention:'Сообщение после тренировки',program:'Сила и движение',workouts:'3 / 3',food:'5 / 7',weight:'68,4',status:'active'},{name:'Михаил Орлов',initials:'МО',goal:'Набор мышц',attention:'Не назначена программа',program:'',workouts:'—',food:'6 / 7',weight:'82,0',status:'active'},{name:'Елена Волкова',initials:'ЕВ',goal:'Поддержание формы',attention:'',program:'Мягкий старт',workouts:'2 / 2',food:'7 / 7',weight:'61,2',status:'active'},{name:'Дмитрий Соколов',initials:'ДС',goal:'Набор мышц',attention:'',program:'Сила и движение',workouts:'3 / 3',food:'6 / 7',weight:'78,5',status:'archived'}];
state.saved = structuredClone(state.program);
const person = () => clients[state.selected];
function currentDays(){state.program.weekDays ??= {}; if(!state.program.weekDays[state.week]) state.program.weekDays[state.week]=structuredClone(state.program.days); return state.program.weekDays[state.week]}
const day = () => currentDays()[state.day] || currentDays()[0];
