 client:()=>`<section class="card pad"><div class="profile"><span class="avatar">${person().initials}</span><div><h3>${esc(person().name)}</h3><p class="muted">${person().goal} · с 12 августа</p></div></div><div class="topline mt"><button class="status-button" data-action="modal:subscription">${tag(state.subscriptionStatus==='frozen'?'Абонемент заморожен':state.subscriptionStatus==='ended'?'Абонемент завершён':'До '+esc(state.subscription.split('-').reverse().join('.')),'green')}${icon('arrow','chev')}</button>${button('Анкета','modal:profile','link')}</div></section>${tabs('client')}${metrics([[person().workouts,'Тренировки','за 7 дней'],[person().food,'Питание','дней из 7'],[person().weight,'Вес, кг','последний замер']])}${section('Следующий шаг')}<section class="card pad"><div class="topline"><strong>${person().program?'Проверить обратную связь':'Настроить сопровождение'}</strong>${tag('Важно','amber')}</div><p class="muted mt">${person().program?'Анна оставила комментарий о нагрузке. Посмотрите тренировку перед ответом.':'Анкета заполнена. Назначьте программу, даты, питание и напоминания.'}</p>${button(person().program?'Открыть сообщение':'Завершить настройку',person().program?'go:messages':'go:setup')}</section>${section('Сопровождение')}${card(row('calendar','Расписание и абонемент','Даты тренировок, срок и продление','go:calendar')+row('message','Сообщения','Обратная связь и ответы','go:messages',tag(state.handled?'0':'1','blue'))+row('check','Задания клиенту','Небольшие действия между тренировками','go:tasks')+row('settings','Напоминания','Тренировки, питание, замеры','modal:reminders'))}<div class="secondary-links">${button('Настройка клиента','go:setup','link')}${button('Действия с клиентом','modal:client-actions','link')}</div>`,
