 progress:()=>`${clientContext()}${tabs('progress')}<section class="card pad"><div class="topline"><span class="muted">Вес · последний месяц</span>${tag('−1,8 кг','green')}</div><p class="big mt">${person().weight} <small>кг</small></p><svg class="chart" viewBox="0 0 310 130" role="img" aria-label="Пример графика: снижение веса за месяц"><path d="M0 20H310 M0 65H310 M0 110H310" stroke="#efeff4"/><path d="M8 25 55 38 102 32 149 64 196 73 243 92 300 108" stroke="#3c6faa"/></svg><div class="chart-labels"><span>12 авг</span><span>26 авг</span><span>7 сен</span></div></section>${section('Замеры тела','modal:measurements','Все 12')}${card(row('chart','Последний замер','7 сентября · сравнить с 12 августа','modal:measurements'))}${section('Фото прогресса')}<section class="card pad"><div class="photo-slots">${['Спереди','Сбоку','Со спины'].map(t=>`<div>${icon('person')}<span>${t}</span></div>`).join('')}</div><p class="muted mt">Фотографии ещё не добавлены.</p><p class="note">После загрузки клиентом — сравнение двух дат в одинаковом ракурсе.</p></section>${button('Напомнить о замерах','modal:measurement-reminder','primary secondary')}`,
